export function redeem(account, cost) {
  if (account.balance < cost) {
    throw new RangeError('[REDEEM]: insufficient balance');
  }
  account.balance -= cost;
  return account;
}

export function retry(fn) {
  let attempts = 3;
  while (true) {
    attempts--;
    try { return fn(); } catch (error) { if (attempts === 0) throw error; }
  }
}
